import type { ListeningExercise, ListeningQuestion } from './ingles-a1-listening'

// The Corner Project — Temporada B1. Continúa la historia de Maya (A2): el edificio del
// café se pone en venta y un rival (Brindle & Co.) quiere demolerlo. 20 episodios en 4
// bloques, mapeados 1:1 con los 20 temas de gramática B1 (mismo orden de la página).
// audioAvailable: false hasta que los MP3 (listening-01..20.mp3) estén grabados y aprobados.

function question(prompt: string, correct: string, wrong: string[], feedback: string): ListeningQuestion {
  const options = [{ label: correct, correct: true, feedback }, ...wrong.map(label => ({ label, correct: false, feedback }))]
  // Rotación determinista: la respuesta correcta no ocupa siempre la misma posición.
  const offset = Array.from(prompt).reduce((sum, character) => sum + character.charCodeAt(0), 0) % options.length
  return { prompt, options: [...options.slice(offset), ...options.slice(0, offset)] }
}

